use super::wire;
use crate::Refusal;

/// Generated by capgen: the calls a plugin can make, one method per capability.
/// Only the kernel's bus gateway implements it; each plugin gets a host bound to
/// its own id, so a plugin never names itself or reaches a provider.
pub trait Host {
    /// Calls wire.store (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_store(
        &self,
        blob: wire::Blob,
        plain: wire::Plain,
        at: u64,
    ) -> Result<wire::Blob, Refusal>;

    /// Calls wire.peek (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_peek(&self, plain: wire::Plain) -> Result<core::option::Option<u64>, Refusal>;

    /// Calls wire.blobs (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_blobs(&self, plain: wire::Plain) -> Result<alloc::vec::Vec<wire::Blob>, Refusal>;

    /// Calls wire.nested (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_nested(
        &self,
        values: alloc::vec::Vec<core::option::Option<u64>>,
    ) -> Result<alloc::vec::Vec<core::option::Option<u64>>, Refusal>;

    /// Calls wire.archive (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_archive(
        &self,
        first: wire::Blob,
        second: wire::Blob,
        values: alloc::vec::Vec<core::option::Option<u64>>,
    ) -> Result<core::option::Option<wire::Blob>, Refusal>;

    /// Calls wire.swap (wire.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn wire_swap(
        &self,
        here: wire::Mode,
        there: super::modes::Mode,
    ) -> Result<super::modes::Mode, Refusal>;
}
